-- Contract table expansion and idempotent import generated from the supplied master list.
ALTER TABLE `project_inventory`
  ADD COLUMN `project_code` varchar(50) DEFAULT NULL AFTER `no`,
  ADD COLUMN `payment_term` varchar(100) DEFAULT NULL AFTER `amount`,
  ADD COLUMN `no_of_pm` decimal(8,2) DEFAULT NULL AFTER `payment_term`,
  ADD COLUMN `pm_y1_q1` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y1_q2` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y1_q3` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y1_q4` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y2_q1` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y2_q2` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y2_q3` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y2_q4` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y3_q1` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y3_q2` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y3_q3` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y3_q4` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y4_q1` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y4_q2` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y4_q3` varchar(50) DEFAULT NULL,
  ADD COLUMN `pm_y4_q4` varchar(50) DEFAULT NULL;

-- Preserve task/file relationships for the existing historical rows.
UPDATE `project_inventory` SET `project_code`=CONCAT('CRS',LPAD(`no`,3,'0')) WHERE `no` BETWEEN 1 AND 211 AND `project_code` LIKE 'PRO/%';

